type HistoryCoverage={chatId:string;status:string;reason:string|null;window:{since:string;until:string;endExclusive:boolean};interpretationProgress?:import('@/lib/kids-history-progress').HistoryInterpretationProgress;transport?:import('@/lib/kids-history-progress').HistoryTransportProgress};
