      {step!=='board'&&k?.mode==='live'&&!data?.liveEnabled&&<div className="kids-gap" role="status"><strong>Managed syncing is paused</strong><p>{data?.service.active?'Live connections are disabled for this beta.':data?.service.message}</p><p>Your saved board, manual changes and export remain available.</p></div>}
