 const targets=connections.map(c=>({bindingId:c.bindingId!,revision:c.revision,sourceEpoch:c.sourceEpoch,chatIds:selected.filter(v=>v.accountId==='hosted:'+c.bindingId).map(v=>v.id)})).filter(t=>t.chatIds.length);
